const DGGRP={neck:['neck','necka','throat'],necka:['neck','necka','throat'],throat:['neck','necka','throat']},DGVN={neck:'Side view',necka:'Front view',throat:'Open mouth'},DGBASE={necka:'neck',throat:'neck'};
`kidney.fat|Perirenal fat cushioning the kidney inside the renal fascia.
kidney.adrenal|Adrenal gland sitting on top of the kidney; it makes cortisol, aldosterone and adrenaline.
kidney.sinus|Renal sinus: fat-filled space in the centre of the kidney holding the calyces, pelvis and vessels.
neck.spine|Cervical vertebrae with the discs between them. They protect the spinal cord and support the head.
neck.cord|Spinal cord running down the vertebral canal from the brainstem.
neck.nasal|Nasal cavity with its turbinates, and the frontal and sphenoid sinuses.
neck.palate|Hard palate (bone) in front and soft palate with the uvula behind; the soft palate closes off the nose when swallowing.
neck.mandible|Lower jaw (the chin bone is cut at the midline) and the teeth.
neck.tongue|Tongue with its muscles; the floor-of-mouth muscles (geniohyoid, mylohyoid) lie beneath it.
neck.epiglottis|Leaf-shaped cartilage that folds over the airway when swallowing. Swells dangerously in epiglottitis.
neck.sternomastoid|Sternocleidomastoid muscle: turns and tilts the head and covers the jugular vein and carotid artery.
neck.clavicle|Collarbones and the top of the breastbone (manubrium) at the base of the neck.
neck.pillars|Tonsillar pillars: the arches of muscle on each side of the throat that frame the tonsils.
neck.teeth|Upper teeth: incisors at the front, then canines, premolars and molars.`.trim().split('\n').forEach(l=>{const i=l.indexOf('|');DGD[l.slice(0,i)]=l.slice(i+1)});
DGD['neck.parotid']='Salivary glands: the parotid in front of the ear and the submandibular under the jaw. Infected in mumps, stones and sialadenitis.';
DGD['neck.hyoid']='U-shaped hyoid bone that anchors the tongue and the larynx; it floats free, attached only by muscles and ligaments.';
DGD['neck.larynx']='Larynx (voice box): the thyroid cartilage forms the Adam\'s apple, and the cricoid cartilage is the only complete ring in the airway.';
DGD['neck.trachea']='Trachea (windpipe): C-shaped cartilage rings keep it open, with a soft muscular wall at the back against the oesophagus.';
DGD['neck.thyroid']='Thyroid gland: two lobes joined by an isthmus in front of the trachea. It makes hormones that control metabolism.';
DGD['neck.parathyroid']='Four small parathyroid glands on the back of the thyroid, shown here seen through it. They control blood calcium.';
DGD['neck.carotid']='Carotid sheath: the common carotid artery (red), the internal jugular vein (blue) and the vagus nerve (yellow) run together.';
function dgS(d){const m=DGM[d.id];if(!m||d.del)return '';const g=DG[m[0]],grp=DGGRP[m[0]],names=[];m[1].forEach(k=>{const kk=k[0]=='-'?k.slice(1):k,v=[m[0]].concat(grp||[]).find(x=>DG[x]&&DG[x].p[kk]),n=v&&DG[v].p[kk][0];if(n&&!names.includes(n))names.push(n)});const svg=dgSvg(m[0],m[1]);return `<div class='sec'><h2>${I('body')} Anatomical diagram</h2><div class='dgw'>${grp?`<div class='dgv' data-hl='${ea(JSON.stringify(m[1]))}'><div class='dgt'>${grp.map(v=>`<button data-dgv='${v}' class='${v==m[0]?'on':''}'>${DGVN[v]}</button>`).join('')}</div>${svg}</div>`:svg}<div style='flex:1;min-width:220px'><p style='margin:0 0 6px'><b>${g.t}</b></p><p style='margin:0 0 6px'>Highlighted: ${names.join(', ')}</p>${m[2]?`<p class='note'>${m[2]}</p>`:''}<div class='dgi'><span class='note'>Hover over or tap any structure to learn what it does.${grp?' Use the buttons above to change the view.':''}</span></div><p class='note'>Schematic diagram for education; real anatomy varies between people.</p></div></div></div>`}
